package com.aicharacter.v3;
import org.json.JSONObject;
/** One linked quadruped body: fore/hind contacts share one trunk and center of mass. */
public final class CatRigState{
 public double gaitPhase,trunkLean,spineFlex,frontLeftContact=1,frontRightContact=1,hindLeftContact=1,hindRightContact=1,frontLoad=.5,hindLoad=.5,lastDistanceSample,frontLeftWorldX=Double.NaN,frontRightWorldX=Double.NaN,hindLeftWorldX=Double.NaN,hindRightWorldX=Double.NaN,frontLeftSlip,frontRightSlip,hindLeftSlip,hindRightSlip,frontLeftRecoveryX=Double.NaN,frontRightRecoveryX=Double.NaN,hindLeftRecoveryX=Double.NaN,hindRightRecoveryX=Double.NaN;
 public JSONObject toJson(){JSONObject j=new JSONObject();try{j.put("gaitPhase",gaitPhase);j.put("trunkLean",trunkLean);j.put("spineFlex",spineFlex);j.put("frontLeftContact",frontLeftContact);j.put("frontRightContact",frontRightContact);j.put("hindLeftContact",hindLeftContact);j.put("hindRightContact",hindRightContact);j.put("frontLoad",frontLoad);j.put("hindLoad",hindLoad);j.put("lastDistanceSample",lastDistanceSample);j.put("frontLeftWorldX",frontLeftWorldX);j.put("frontRightWorldX",frontRightWorldX);j.put("hindLeftWorldX",hindLeftWorldX);j.put("hindRightWorldX",hindRightWorldX);j.put("frontLeftSlip",frontLeftSlip);j.put("frontRightSlip",frontRightSlip);j.put("hindLeftSlip",hindLeftSlip);j.put("hindRightSlip",hindRightSlip);j.put("frontLeftRecoveryX",frontLeftRecoveryX);j.put("frontRightRecoveryX",frontRightRecoveryX);j.put("hindLeftRecoveryX",hindLeftRecoveryX);j.put("hindRightRecoveryX",hindRightRecoveryX);}catch(Exception ignored){}return j;}
 public static CatRigState fromJson(JSONObject j){CatRigState c=new CatRigState();if(j==null)return c;c.gaitPhase=j.optDouble("gaitPhase");c.trunkLean=j.optDouble("trunkLean");c.spineFlex=j.optDouble("spineFlex");c.frontLeftContact=j.optDouble("frontLeftContact",1);c.frontRightContact=j.optDouble("frontRightContact",1);c.hindLeftContact=j.optDouble("hindLeftContact",1);c.hindRightContact=j.optDouble("hindRightContact",1);c.frontLoad=j.optDouble("frontLoad",.5);c.hindLoad=j.optDouble("hindLoad",.5);c.lastDistanceSample=Math.max(0,j.optDouble("lastDistanceSample"));c.frontLeftWorldX=j.has("frontLeftWorldX")?j.optDouble("frontLeftWorldX"):Double.NaN;c.frontRightWorldX=j.has("frontRightWorldX")?j.optDouble("frontRightWorldX"):Double.NaN;c.hindLeftWorldX=j.has("hindLeftWorldX")?j.optDouble("hindLeftWorldX"):Double.NaN;c.hindRightWorldX=j.has("hindRightWorldX")?j.optDouble("hindRightWorldX"):Double.NaN;c.frontLeftSlip=cl(j.optDouble("frontLeftSlip"));c.frontRightSlip=cl(j.optDouble("frontRightSlip"));c.hindLeftSlip=cl(j.optDouble("hindLeftSlip"));c.hindRightSlip=cl(j.optDouble("hindRightSlip"));c.frontLeftRecoveryX=j.has("frontLeftRecoveryX")?j.optDouble("frontLeftRecoveryX"):Double.NaN;c.frontRightRecoveryX=j.has("frontRightRecoveryX")?j.optDouble("frontRightRecoveryX"):Double.NaN;c.hindLeftRecoveryX=j.has("hindLeftRecoveryX")?j.optDouble("hindLeftRecoveryX"):Double.NaN;c.hindRightRecoveryX=j.has("hindRightRecoveryX")?j.optDouble("hindRightRecoveryX"):Double.NaN;return c;}private static double cl(double v){return Math.max(0,Math.min(1,v));}
}